type Item = { menu: string; harga: number; jumlah: number };
type Promo = (total: number) => number;

const subtotal = (item: Item): number => item.harga * item.jumlah;
function hitung(items: Item[], promo: Promo = (t) => t): number {
  const total = items.reduce((a, i) => a + subtotal(i), 0);
  return promo(total);
}
const potong5000: Promo = (t) => (t >= 50000 ? t - 5000 : t);

const pesanan: Item[] = [
  { menu: "Kopi", harga: 18000, jumlah: 2 },
  { menu: "Roti", harga: 15000, jumlah: 1 },
];
console.log(hitung(pesanan));
console.log(hitung(pesanan, potong5000));

