type Item = { menu: string; harga: number; jumlah: number };
type Promo = (total: number) => number;
function tolak(pesan: string): never {
  throw new Error(pesan);
}
const subtotal = (item: Item): number => item.harga * item.jumlah;
function hitung(items: Item[], promo: Promo = (t) => t): number {
  for (const i of items) {
    if (i.jumlah <= 0) tolak(`Jumlah ${i.menu} tidak valid`);
  }
  const total = items.reduce((a, i) => a + subtotal(i), 0);
  return promo(total);
}
const pesanan: Item[] = [
  { menu: "Kopi", harga: 18000, jumlah: 2 },
  { menu: "Roti", harga: 15000, jumlah: 1 },
];
const diskon10: Promo = (t) => Math.round(t * 0.9);
console.log(hitung(pesanan));
console.log(hitung(pesanan, diskon10));
try {
  hitung([{ menu: "Teh", harga: 12000, jumlah: 0 }]);
} catch (e) {
  if (e instanceof Error) console.log("Ditolak:", e.message);
}

