type Item = { menu: string; harga: number; jumlah: number };
function ringkas(items: Item[]): string {
  const banyak = items.reduce((a, i) => a + i.jumlah, 0);
  const total = items.reduce((a, i) => a + i.harga * i.jumlah, 0);
  return `${banyak} item, total ${total}`;
}
console.log(ringkas([
  { menu: "Kopi", harga: 18000, jumlah: 2 },
  { menu: "Roti", harga: 15000, jumlah: 1 },
  { menu: "Teh", harga: 12000, jumlah: 3 },
]));
